#!/usr/bin/env python3
"""Generate the Earth-control Metal kernel from its canonical GLSL source."""
import argparse
from generate_tke_msl import ROOT, translate


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    target = ROOT / "metal/include/compute/metal/shaders/chaos/earth_control_evolution_msl.hpp"
    source = translate("earth_control_evolution", "chaos").replace(
        "Generated by scripts/dev/shaders/generate_tke_msl.py",
        "Generated by scripts/dev/shaders/generate_earth_control_msl.py",
    )
    if args.check:
        if not target.is_file() or target.read_text() != source:
            raise RuntimeError("Earth-control Metal source is stale")
    else:
        target.write_text(source)


if __name__ == "__main__":
    main()
